insert into public.contingency_plans (id, code, title, hazard_code, scenario, warning_time, activation_triggers, status, adopted_ref, adopted_on, valid_until, vault_document_id) values
('f608bb90-0195-50b8-9ff3-0213328a196d'::uuid, 'CP-FLOOD-LUNOP', 'Enhanced Contingency Plan for flood-affected barangays ("Oplan Lunop")', 'flood', 'Typhoon with flood and storm surge', '1-3 days (PAGASA)', 'Blue on forecast landfall; Red at Tropical Cyclone Wind Signal No. 2 or a flood or storm-surge warning. RA 12287 path when the lead time is 72 hours or more.', 'adopted', 'CDRRMC Res. No. 2-A, s. 2021', '2021-05-03'::date, null::date, (select id from public.vault_documents where id = 'efd87392-d1fd-5110-afb7-ffd9b98038d8'::uuid)),
('2548f9ea-6875-570b-a58f-f40e23ce242e'::uuid, 'CP-EARTHQUAKE', 'Enhanced Contingency Plan for Earthquake (2020-2025)', 'earthquake', 'Earthquake on the Philippine Fault, with liquefaction, landslides and local tsunami', 'None', 'Red automatically on strong shaking or a PHIVOLCS bulletin; staff report without being called. Move to the alternate EOC if the primary is damaged.', 'expired', 'CDRRMC Res. No. 2-B, s. 2021', '2021-05-03'::date, '2025-12-31'::date, (select id from public.vault_documents where id = 'a5ca7300-4b31-5d59-a946-eddecdb2244e'::uuid)),
('c556ad66-a171-59fb-abb2-9f4f0977138a'::uuid, 'CP-FLASHFLOOD', 'Contingency plan for flash floods (Anilao-Malbasag system)', 'flash_flood', 'Flash flood', 'Hours', 'Red straight from an orange or red heavy-rainfall warning; usually below the 72-hour declaration floor, so city early action applies.', 'to_prepare', null, null::date, null::date, (select id from public.vault_documents where id = null)),
('69cb356d-4217-5eac-a41a-8ae3cc1bcf1b'::uuid, 'CP-LANDSLIDE', 'Contingency plan for landslides in the uplands', 'rain_landslide', 'Landslide, uplands (rain or earthquake)', 'Hours to none', 'Blue on rainfall thresholds; Red if there are mass casualties or barangays are cut off. The IMT leads on site.', 'to_prepare', null, null::date, null::date, (select id from public.vault_documents where id = null)),
('f42766ec-cd0f-5e95-836a-4523d5298c5c'::uuid, 'CP-DROUGHT', 'Contingency plan for El Nino / drought', 'drought', 'El Nino / drought', 'Months', 'White or Blue only; the El Nino Task Force (EO No. 2023-0042) coordinates. No Red.', 'to_prepare', null, null::date, null::date, (select id from public.vault_documents where id = null)),
('65a0c281-83a6-5e4c-9d4d-7c159d6ffe59'::uuid, 'CP-DISEASE', 'Contingency plan for emerging and re-emerging diseases', null, 'Disease outbreak', 'Days to weeks', 'Blue; Red at the Health Cluster''s request. Plan still to be written (CDP PPA 2.15).', 'to_prepare', null, null::date, null::date, (select id from public.vault_documents where id = null)),
('5dbc72ee-d4a9-5451-b428-a0849ff4e0bd'::uuid, 'CP-INDUSTRIAL', 'Contingency plan for industrial or geothermal incidents, fire and planned events', 'industrial', 'Industrial or geothermal incident, fire, planned event', 'None, or scheduled', 'Blue as needed; IMT under CDRRMC Res. No. 09 s. 2024.', 'to_prepare', null, null::date, null::date, (select id from public.vault_documents where id = null))
